def get_account_type():
    """Ask the user for their account type (checking or savings)."""
    while True:
        account_type = input("Enter 'checking' or 'savings': ").lower()
        if account_type in ['checking', 'savings']:
            return account_type
        else:
            print("Invalid account type. Please enter 'checking' or 'savings'.")

def get_transaction_type():
    """Ask the user for the transaction type (deposit or withdrawal)."""
    while True:
        transaction_type = input("Enter 'deposit' or 'withdrawal': ").lower()
        if transaction_type in ['deposit', 'withdrawal']:
            return transaction_type
        else:
            print("Invalid transaction type. Please enter 'deposit' or 'withdrawal'.")

def apply_fees(account_type, transaction_type, amount):
    """Apply the corresponding fees based on the account type and transaction type."""
    if account_type == 'checking':
        if transaction_type == 'withdrawal':
            return amount * 0.5  # 5% fee for withdrawals
        else:
            return amount
    elif account_type == 'savings':
        if transaction_type == 'withdrawal':
            return amount * 0.2  # 20% fee for withdrawals
        else:
            return amount * 1.05  # 5% interest on deposits
    else:
        raise ValueError("Invalid account type. Please enter 'checking' or 'savings'.")

def calculate_balance(account_type, transaction_type, amount):
    """Calculate the new balance based on the fees and the transaction amount."""
    fees = apply_fees(account_type, transaction_type, amount)
    new_balance = amount - fees
    return new_balance

def main():
    account_type = get_account_type()
    transaction_type = get_transaction_type()
    deposit_amount = float(input(f"Enter the amount for {transaction_type} (checking): $"))
    new_balance = calculate_balance(account_type, transaction_type, deposit_amount)
    print(f"New balance: ${new_balance:.2f}")

if __name__ == "__main__":
